ALTER TABLE users ADD COLUMN phone TEXT DEFAULT '';
CREATE TABLE categories(id INTEGER PRIMARY KEY,name TEXT UNIQUE NOT NULL);
CREATE TABLE mentors(id INTEGER PRIMARY KEY,name TEXT NOT NULL,info TEXT DEFAULT '',image TEXT DEFAULT '');
CREATE TABLE courses(id INTEGER PRIMARY KEY,slug TEXT UNIQUE NOT NULL,name TEXT NOT NULL,category_id INTEGER REFERENCES categories(id),price INTEGER NOT NULL DEFAULT 0,months INTEGER NOT NULL DEFAULT 3,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN('draft','published','archived')),description TEXT DEFAULT '',image TEXT DEFAULT '',syllabus TEXT DEFAULT '[]',skills TEXT DEFAULT '[]',outcomes TEXT DEFAULT '[]');
CREATE TABLE course_mentors(course_id INTEGER REFERENCES courses(id) ON DELETE CASCADE,mentor_id INTEGER REFERENCES mentors(id) ON DELETE CASCADE,PRIMARY KEY(course_id,mentor_id));
CREATE TABLE modules(id INTEGER PRIMARY KEY,course_id INTEGER NOT NULL REFERENCES courses(id) ON DELETE CASCADE,title TEXT NOT NULL,position INTEGER NOT NULL DEFAULT 0);
CREATE TABLE lessons(id INTEGER PRIMARY KEY,module_id INTEGER NOT NULL REFERENCES modules(id) ON DELETE CASCADE,title TEXT NOT NULL,video_url TEXT DEFAULT '',position INTEGER NOT NULL DEFAULT 0);
CREATE TABLE resources(id INTEGER PRIMARY KEY,course_id INTEGER NOT NULL REFERENCES courses(id) ON DELETE CASCADE,title TEXT NOT NULL,url TEXT NOT NULL);
CREATE TABLE enrollments(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,course_id INTEGER NOT NULL REFERENCES courses(id),status TEXT NOT NULL DEFAULT 'active' CHECK(status IN('active','inactive')),created_at INTEGER NOT NULL,UNIQUE(user_id,course_id));
